const d = $input.first().json;
const wf = (d.workflow && d.workflow.name) || 'unknown workflow';
const exec = d.execution || {};
const err = exec.error || {};
const node = exec.lastNodeExecuted || (err.node && err.node.name) || 'unknown node';

const when = new Date().toLocaleString('en-AU', { timeZone: 'Australia/Sydney', dateStyle: 'medium', timeStyle: 'short' });

const lines = [
  '\uD83D\uDEA8 n8n workflow ERROR (' + when + ' AEST)',
  'Workflow: ' + wf,
  'Failed node: ' + node,
  'Error: ' + (err.message || 'no message captured'),
  exec.url ? 'Execution: ' + exec.url : (exec.id ? 'Execution id: ' + exec.id : '')
];

return [{ json: { message: lines.filter(Boolean).join('\n') } }];
